import 'package:fluent_ui/fluent_ui.dart';import 'package:flutter_bloc/flutter_bloc.dart';import 'theme_cubit.dart';class SettingsPage extends StatelessWidget{const SettingsPage({super.key});@override Widget build(BuildContext context){final m=context.watch<ThemeCubit>().state;return ScaffoldPage.scrollable(header:const PageHeader(title:Text('Settings')),children:[Card(padding:const EdgeInsets.all(20),child:Row(children:[const Icon(FluentIcons.color),const SizedBox(width:12),const Expanded(child:Text('Application theme')),ComboBox<ThemeMode>(value:m,items:const[ComboBoxItem(value:ThemeMode.system,child:Text('System')),ComboBoxItem(value:ThemeMode.light,child:Text('Light')),ComboBoxItem(value:ThemeMode.dark,child:Text('Dark'))],onChanged:(v){if(v!=null)context.read<ThemeCubit>().setMode(v);})])),const SizedBox(height:16),const InfoBar(title:Text('Log file'),content:Text('Logs are stored in the Windows temporary directory as windows_system_dashboard.log.'))]);}}
